'use strict';
// Original present-day fiction. The source motif and our interpretation are
// deliberately separate; these choices never generate a personality result.
fables.push(
 {id:'thread',title:'Bas ek dhaaga',description:'Uncertainty: a map is missing, but a way back can still exist.',note:'Original fiction using Ariadne’s thread as an image. Apollodorus, Epitome 1.8–9 describes the thread used to retrace a labyrinth; the choices and meaning here are ours. The full myth includes violence.',art:'waves',sourceURL:'https://www.theoi.com/Text/ApollodorusE.html',sourceLabel:'Ariadne’s thread · Apollodorus, Epitome 1.8–9',nodes:{start:{text:'Ek courtyard mein raaste teen taraf jaate hain. Tum poora map maangte ho. Saath chalne wala ek dhaaga dikhata hai: “Poora jawab nahi. Bas wapas aane ka ek nishaan.” Ab?',choices:[['Ek chhoti cheez pata karein','ask'],['Pehle rukne ki jagah banaayein','pause']]},ask:{text:'Tum poochhte ho, “Agla mod kahan hai?” Saare raaste clear nahi hote. Bas ek actual jawab milta hai. Tum uske paas apna nishaan rakhte ho.',choices:[['Is jawab ke saath ek kadam','end-step'],['Abhi itni clarity kaafi','end-pause']]},pause:{text:'Tum dhaaga ek stable jagah par rakhte ho. Rukne se raaste gayab nahi hote. Abhi tumhe apni saans ya body ko observe karna bhi zaroori nahi—bas courtyard ko dekh sakte ho.',choices:[['Yahin kahaani ko pause dein','end-pause'],['Ek sawal choose karein','end-step']]},'end-step':{text:'Tum poore bhavishya ka promise liye bina ek mod tak jaate ho. Kahaani us mod par rukti hai; tum agla kadam baad mein choose kar sakte ho.',end:true,reflection:'Kya abhi tumhe poora jawab chahiye, ya ek useful piece of information?',step:'Write one question that someone could actually answer today.'},'end-pause':{text:'Dhaaga apni jagah hai. Tum courtyard mein baith jaate ho. Kahaani ko aaj maze ke end tak jaana zaroori nahi.',end:true,reflection:'Uncertainty ko pause dena uska jawab mil jaana nahi. Phir bhi pause tumhara option hai.',step:'Choose one decision that can safely wait until tomorrow.'}}},
 {id:'comparison',title:'Do alag kitaabein',description:'Comparison: what if the room’s ranking isn’t your whole story?',note:'Original fiction inspired by the gatekeeping theme in the Ashtavakra court episode (Mahabharata, Vana Parva 133). This is not a retelling or a claim that you must prove exceptional ability to deserve respect.',art:'gate',sourceURL:'#source/2/1',sourceLabel:'Ashtavakra at the gate · source reader',nodes:{start:{text:'Ek reading room mein sabke haath mein alag kitaab hai. Board par sirf “Kitne pages?” likha hai. Tum apni kitaab dekhte ho—usmein notes aur khaali jagah bhi hai. Kya karein?',choices:[['Apne page ko dekhein','mine'],['Board se thodi door chalein','outside']]},mine:{text:'Ek reader kehta hai, “Main toh kaafi aage hoon.” Tumhari kitaab ka chapter usse alag hai. Comparison ki chubhan reh sakti hai, bina usse apni poori value banaye.',choices:[['Apni ek khwahish pehchaanein','end-want'],['Aaj numbers chhod dein','end-space']]},outside:{text:'Courtyard mein board nazar nahi aata. Tum notice karte ho: shayad tumhe unki speed nahi, apne liye thoda waqt chahiye. Shayad kuch aur. Tum decide kar sakte ho.',choices:[['Waqt ki jagah banaayein','end-space'],['Mujhe kya chahiye?','end-want']]},'end-want':{text:'Tum ek slip par likhte ho, “Mujhe bhi…” Slip ranking nahi banati. Bas tumhari apni ek khwahish ko words milte hain.',end:true,reflection:'Comparison ke neeche koi apni khwahish hai? Jawab “pata nahi” bhi ho sakta hai.',step:'Name one thing you want for yourself, without mentioning anyone else.'},'end-space':{text:'Kitaab band nahi hoti. Board bhi mita nahi. Tum uske saamne khade rehne ka waqt thoda kam karte ho.',end:true,reflection:'Kisi comparison se door rehna apne goals chhodna nahi hota.',step:'Choose one comparison-heavy feed or conversation to pause for today.'}}},
 {id:'rejection',title:'Ek darwaaza, poori duniya nahi',description:'Rejection: a closed room, a companion, and another place to sit.',note:'Original fiction drawing on the doorway motif in the Ashtavakra episode. The original episode continues differently; these alternate paths are invented. A closed door can hurt without defining your worth.',art:'gate',sourceURL:'#source/2/1',sourceLabel:'The original doorway episode · source reader',nodes:{start:{text:'Ek room se jawab aata hai: “Aaj nahi.” Tumhare haath mein abhi bhi apna sawal hai. Saath khada musafir poochhta hai, “Is waqt company chahiye ya thodi jagah?”',choices:[['Company','company'],['Thodi jagah','space']]},company:{text:'Musafir yeh nahi kehta ki sab achhe ke liye hua. Woh bas paas baithta hai. “Samjhaun, ya sunun?”',choices:[['Bas suno','end-company'],['Kal ka ek practical sawal','end-space']]},space:{text:'Tum ek bench par jaate ho. Room ki baat abhi chubh rahi hai. Tumhe turant positive meaning ya doosra opportunity dhoondhna zaroori nahi.',choices:[['Aaj bas itna','end-space'],['Kisi apne ko message','end-company']]},'end-company':{text:'Tum ek sentence kehte ho: “Yeh hurt hua.” Musafir sunta hai. Tumhari baat ko courtroom ka evidence nahi banna padta.',end:true,reflection:'Support maangne ke liye hurt ko justify karna zaroori nahi.',step:'If it feels safe, tell someone: “I don’t need advice yet. Could you listen?”'},'end-space':{text:'Bench par tum apna sawal paas rakh dete ho. Aaj ka “nahi” poori zindagi ka answer nahi banaya jaata. Aage ka meaning khula reh sakta hai.',end:true,reflection:'Kya abhi rest ki jagah chahiye, practical clarity, ya dono?',step:'Choose one kind thing for the next ten minutes; an explanation can wait.'}}},
 {id:'boundaries',title:'Dhaage ka doosra sira',description:'Boundaries: helping someone without dropping every part of your own day.',note:'Original fiction borrowing the image of Ariadne’s thread, not an ancient lesson about boundaries. These choices are modern reflections and may not fit every relationship or safety situation.',art:'waves',sourceURL:'https://www.theoi.com/Text/ApollodorusE.html',sourceLabel:'Thread motif · Apollodorus 1.8–9 (full myth includes violence)',nodes:{start:{text:'Ek musafir tumse kehta hai, “Poora raasta mere saath chalo.” Tum madad karna chahte ho, par aaj tumhari energy kam hai. Tumhare haath mein dhaage ka ek sira hai. Kya keh sakte ho?',choices:[['Main itna kar sakta hoon…','limit'],['Abhi jawab dene ka waqt chahiye','time']]},limit:{text:'Tum kehte ho, “Main agle mod tak saath aa sakta hoon.” Musafir disappointed lag sakta hai. Tumhara limit us feeling ko turant mita nahi sakta.',choices:[['Apni baat simple rakhein','end-limit'],['Doosra option suggest karein','end-time']]},time:{text:'Tum kehte ho, “Main abhi promise nahi kar sakta. Thodi der mein bataunga.” Poora explanation dena zaroori nahi, agar aisa kehna tumhare liye safe hai.',choices:[['Jawab ke liye waqt rakhein','end-time'],['Ek clear limit choose karein','end-limit']]},'end-limit':{text:'Tum ek sira pakde rehte ho. Saamne wale ki poori journey tumhari eklauti zimmedari nahi banti. Conversation ka outcome abhi khula hai.',end:true,reflection:'Care aur apni limit ek sentence mein saath aa sakte hain.',step:'Try a sentence privately: “I care, and today I can only…”'},'end-time':{text:'Dhaaga floor par ek chhota curve banata hai. Tumne abhi sirf jawab ke liye jagah maangi hai. Kahaani yahin ruk sakti hai.',end:true,reflection:'Har request ka immediate answer dena zaroori nahi. Unsafe situations may need a different plan and support.',step:'Draft a safe reply: “Let me check what I can manage and get back to you.”'}}}
);
